body.script:
// the same snow and tracking bar main.js runs on the scroll page
(() => {
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const nc = document.querySelector(".vhs-noise"), x = nc.getContext("2d"); nc.width = 320; nc.height = 200;
  const img = x.createImageData(nc.width, nc.height), d = img.data;
  let last = 0;
  const noise = now => { if (now - last > 70) { for (let i = 0; i < d.length; i += 4) { const v = (Math.random() * 255) | 0; d[i] = d[i + 1] = d[i + 2] = v; d[i + 3] = 255; } x.putImageData(img, 0, 0); last = now; } requestAnimationFrame(noise); };
  if (!reduced) requestAnimationFrame(noise);
  const track = document.querySelector(".vhs-track");
  const roll = () => {
    const wait = 3000 + Math.random() * 6000, dur = 1200 + Math.random() * 1200;
    setTimeout(() => {
      track.style.transition = "none"; track.style.top = "-12%"; track.style.opacity = "1";
      requestAnimationFrame(() => requestAnimationFrame(() => { track.style.transition = `top ${dur}ms linear`; track.style.top = "110%"; }));
      setTimeout(() => { track.style.opacity = "0"; roll(); }, dur + 50);
    }, wait);
  };
  if (!reduced) roll();
})();
